function raLogin(string $username,string $password='FixturePass!42') {$client=misClient();$page=misRequest($client,'/auth/login.php');$result=misRequest($client,'/auth/login.php',['csrf_token'=>misField($page,'csrf_token'),'identifier'=>$username,'password'=>$password]);if($result['status']!==302)throw new RuntimeException('Reauthentication fixture login failed.');return $client;}
function raExpire($client): void {foreach(curl_getinfo($client,CURLINFO_COOKIELIST) as $cookie){$parts=explode("\t",$cookie);if(($parts[5]??'')==='PHPSESSID'&&preg_match('/^[A-Za-z0-9,-]+$/D',$parts[6]??'')){$file=__DIR__.'/../scratch/sess_'.$parts[6];$contents=file_get_contents($file);$contents=preg_replace('/last_activity\|i:[0-9]+;/','last_activity|i:'.(time()-7200).';',$contents,1,$count);if($count!==1)throw new RuntimeException('Synthetic session timestamp unavailable.');file_put_contents($file,$contents);return;}}throw new RuntimeException('Synthetic session unavailable.');}
function raAgePasswordProof($client): void {foreach(curl_getinfo($client,CURLINFO_COOKIELIST) as $cookie){$parts=explode("\t",$cookie);if(($parts[5]??'')==='PHPSESSID'&&preg_match('/^[A-Za-z0-9,-]+$/D',$parts[6]??'')){$file=__DIR__.'/../scratch/sess_'.$parts[6];$contents=file_get_contents($file);$contents=preg_replace('/password_confirmed_at\|i:[0-9]+;/','password_confirmed_at|i:'.(time()-600).';',$contents,1,$count);if($count!==1)throw new RuntimeException('Password proof missing');file_put_contents($file,$contents);return;}}throw new RuntimeException('Synthetic session unavailable.');}
function raRequest($client,string $path,?array $body=null,array $headers=[]): array {global $base;$received=[];curl_setopt_array($client,[CURLOPT_URL=>$base.$path,CURLOPT_POST=>$body!==null,CURLOPT_HTTPHEADER=>$headers,CURLOPT_HEADERFUNCTION=>function($c,$line)use(&$received){if(str_contains($line,':')){[$key,$value]=explode(':',$line,2);$received[strtolower($key)]=trim($value);}return strlen($line);}]);if($body!==null)curl_setopt($client,CURLOPT_POSTFIELDS,http_build_query($body));$response=curl_exec($client);if($response===false)throw new RuntimeException('Reauthentication HTTP request failed');return ['status'=>curl_getinfo($client,CURLINFO_RESPONSE_CODE),'body'=>$response,'headers'=>$received];}
